// Helper: Obține toate cheltuielile din toate lunile (fără Economii & Rate, fără tranzacții suspendate)
function getAllActiveExpenseTransactions() {
    if (!appData || !Array.isArray(appData.transactions)) return [];
    return appData.transactions.filter(t => 
        t && 
        t.type === 'expense' && 
        t.date && 
        !isSavingsCategory(t) && 
        !isTxEffectivelySuspended(t)
    );
}

// Grafic: Distribuție Cheltuieli pe Zilele Săptămânii (Luni - Duminică, cumulat din toate lunile)
function renderStatsWeekdayChart(txList, mainCurr, curSymbol, activeLang) {
    const canvas = document.getElementById('statsWeekdayChart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const daySumsRon = [0, 0, 0, 0, 0, 0, 0]; // 0=Lun, 1=Mar, 2=Mie, 3=Joi, 4=Vin, 5=Sam, 6=Dum
    const targetTxs = (Array.isArray(txList) && txList.length > 0) ? txList : getAllActiveExpenseTransactions();

    targetTxs.forEach(t => {
        if (!t.date || t.type !== 'expense' || isSavingsCategory(t) || isTxEffectivelySuspended(t)) return;
        const d = new Date(t.date + 'T12:00:00');
        const day = d.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat
        const mappedIdx = (day + 6) % 7; // 0=Mon, ..., 6=Sun
        const amtRon = parseFloat(t.amountInRon) || parseFloat(t.amount) || 0;
        daySumsRon[mappedIdx] += amtRon;
    });

    const daySumsDisp = daySumsRon.map(v => convertFromRon(v, mainCurr));


    const dayLabelsMap = {
        ro: ['Lun', 'Mar', 'Mie', 'Joi', 'Vin', 'Sâm', 'Dum'],
        en: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
        de: ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'],
        tr: ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'],
        ja: ['月', '火', '水', '木', '金', '土', '日'],
        zh: ['周一', '周二', '周三', '周四', '周五', '周六', '周日']
    };
    const dayLabels = dayLabelsMap[activeLang] || dayLabelsMap['ro'];

    const chartTextColor = getChartTextColor();
    const chartGridColor = getChartGridColor();

    if (statsWeekdayChartInstance) {
        statsWeekdayChartInstance.destroy();
    }
    statsWeekdayChartInstance = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: dayLabels,
            datasets: [{
                label: `${t('stat_expense')} (${curSymbol})`,
                data: daySumsDisp,
                backgroundColor: 'rgba(59, 130, 246, 0.8)',
                hoverBackgroundColor: '#3b82f6',
                borderRadius: 4,
                barPercentage: 0.6
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { color: chartTextColor, font: { size: 10 } }
                },
                y: {
                    grid: { color: chartGridColor },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 10 },
                        callback: (v) => v + ' ' + curSymbol
                    }
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: (ctx) => ` ${formatMoney(ctx.raw, mainCurr)}`
                    }
                },
                datalabels: { display: false }
            }
        }
    });
}

// Calcul Sold Curent Total pentru Autonomie Financiară (Runway)
function calculateTotalBalance() {
    let totalBalRon = 0;
    appData.transactions.forEach(t => {
        if (isTxSuspended(t)) return;
        const a = parseFloat(t.amountInRon) || parseFloat(t.amount) || 0;
        if (t.type === 'income') totalBalRon += a;
        else if (t.type === 'expense') totalBalRon -= a;
    });
    return totalBalRon;
}

// Functie auxiliara pentru extragerea orei tranzactiei (0 - 23)
function getTransactionHour(t) {
    if (t.time && typeof t.time === 'string' && t.time.includes(':')) {
        const h = parseInt(t.time.split(':')[0], 10);
        if (!isNaN(h) && h >= 0 && h <= 23) return h;
    }
    if (t.createdAt) {
        const d = new Date(t.createdAt);
        if (!isNaN(d.getTime())) return d.getHours();
    }
    if (t.id && typeof t.id === 'string' && t.id.startsWith('tx-')) {
        const parts = t.id.split('-');
        const ts = parseInt(parts[1], 10);
        if (!isNaN(ts) && ts > 1600000000000) {
            const d = new Date(ts);
            if (!isNaN(d.getTime())) return d.getHours();
        }
    }
    return null;
}

// Grafic 2: Distribuție Cheltuieli pe Interval Orar (00:00 - 23:00, cumulat din toate lunile)
function renderStatsHourlyChart(txList, mainCurr, curSymbol, activeLang) {
    const canvas = document.getElementById('statsHourlyChart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const badgeEl = document.getElementById('statsPeakHourBadge');

    const hourlySumsRon = new Array(24).fill(0);
    const hourlyCounts = new Array(24).fill(0);
    const targetTxs = (Array.isArray(txList) && txList.length > 0) ? txList : getAllActiveExpenseTransactions();

    targetTxs.forEach(t => {
        if (t.type !== 'expense' || isSavingsCategory(t) || isTxEffectivelySuspended(t)) return;
        const h = getTransactionHour(t);
        const amtRon = parseFloat(t.amountInRon) || parseFloat(t.amount) || 0;
        if (h !== null && h >= 0 && h <= 23) {
            hourlySumsRon[h] += amtRon;
            hourlyCounts[h]++;
        }
    });


    // Identificare ora de varf
    let peakHour = -1;
    let peakSumRon = 0;
    for (let i = 0; i < 24; i++) {
        if (hourlySumsRon[i] > peakSumRon) {
            peakSumRon = hourlySumsRon[i];
            peakHour = i;
        }
    }

    if (badgeEl) {
        if (peakHour !== -1 && peakSumRon > 0) {
            const nextH = (peakHour + 1) % 24;
            const hStr = `${String(peakHour).padStart(2, '0')}:00–${String(nextH).padStart(2, '0')}:00`;
            const peakDisp = formatMoney(convertFromRon(peakSumRon, mainCurr), mainCurr);
            badgeEl.textContent = `⚡ Vârf: ${hStr} (${peakDisp})`;
            badgeEl.style.display = 'inline-block';
        } else {
            badgeEl.style.display = 'none';
        }
    }

    const hourlySumsDisp = hourlySumsRon.map(v => convertFromRon(v, mainCurr));

    // Etichete de la 00h la 23h
    const hourLabels = [
        '00h', '01h', '02h', '03h', '04h', '05h', '06h', '07h', '08h', '09h', '10h', '11h',
        '12h', '13h', '14h', '15h', '16h', '17h', '18h', '19h', '20h', '21h', '22h', '23h'
    ];

    // Culori: evidentiere pe bara cu cea mai mare cheltuiala
    const bgColors = hourlySumsRon.map(val => (val > 0 && val === peakSumRon) ? '#f59e0b' : 'rgba(245, 158, 11, 0.55)');
    const hoverColors = hourlySumsRon.map(val => (val > 0 && val === peakSumRon) ? '#d97706' : '#f59e0b');

    const chartTextColor = getChartTextColor();
    const chartGridColor = getChartGridColor();

    if (statsHourlyChartInstance) {
        statsHourlyChartInstance.destroy();
    }

    statsHourlyChartInstance = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: hourLabels,
            datasets: [{
                label: `${t('stat_expense')} (${curSymbol})`,
                data: hourlySumsDisp,
                backgroundColor: bgColors,
                hoverBackgroundColor: hoverColors,
                borderRadius: 3,
                barPercentage: 0.75
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    grid: { display: false },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 9 },
                        maxRotation: 0,
                        autoSkip: true,
                        maxTicksLimit: 12
                    }
                },
                y: {
                    grid: { color: chartGridColor },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 10 },
                        callback: (v) => v + ' ' + curSymbol
                    }
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        title: (items) => {
                            const idx = items[0].dataIndex;
                            const nextH = (idx + 1) % 24;
                            return `Interval ${String(idx).padStart(2, '0')}:00 – ${String(nextH).padStart(2, '0')}:00`;
                        },
                        label: (ctx) => {
                            const count = hourlyCounts[ctx.dataIndex];
                            const countTxt = activeLang === 'ro' ? `${count} plăți` : `${count} tx`;
                            return ` ${formatMoney(ctx.raw, mainCurr)} (${countTxt})`;
                        }
                    }
                },
                datalabels: { display: false }
            }
        }
    });
}

// Grafic 3: Distribuție Cheltuieli pe Zilele Lunii (1 - 31, cumulat din toate lunile)
function renderStatsMonthDaysChart(txList, mainCurr, curSymbol, activeLang) {
    const canvas = document.getElementById('statsMonthDaysChart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const badgeEl = document.getElementById('statsPeakMonthDayBadge');

    const monthDaySumsRon = new Array(31).fill(0);
    const monthDayCounts = new Array(31).fill(0);
    const targetTxs = (Array.isArray(txList) && txList.length > 0) ? txList : getAllActiveExpenseTransactions();

    targetTxs.forEach(t => {
        if (!t.date || typeof t.date !== 'string' || t.type !== 'expense' || isSavingsCategory(t) || isTxEffectivelySuspended(t)) return;
        const parts = t.date.split('-');
        if (parts.length >= 3) {
            const dayNum = parseInt(parts[2], 10);
            if (!isNaN(dayNum) && dayNum >= 1 && dayNum <= 31) {
                const amtRon = parseFloat(t.amountInRon) || parseFloat(t.amount) || 0;
                monthDaySumsRon[dayNum - 1] += amtRon;
                monthDayCounts[dayNum - 1]++;
            }
        }
    });


    // Identificare ziua de vârf a lunii
    let peakDayIdx = -1;
    let peakSumRon = 0;
    for (let i = 0; i < 31; i++) {
        if (monthDaySumsRon[i] > peakSumRon) {
            peakSumRon = monthDaySumsRon[i];
            peakDayIdx = i;
        }
    }

    if (badgeEl) {
        if (peakDayIdx !== -1 && peakSumRon > 0) {
            const dayStr = peakDayIdx + 1;
            const peakDisp = formatMoney(convertFromRon(peakSumRon, mainCurr), mainCurr);
            const peakLabel = activeLang === 'ro' ? `⚡ Vârf: Ziua ${dayStr} (${peakDisp})` :
                              activeLang === 'de' ? `⚡ Spitze: Tag ${dayStr} (${peakDisp})` :
                              activeLang === 'tr' ? `⚡ Zirve: Gün ${dayStr} (${peakDisp})` :
                              activeLang === 'zh' ? `⚡ 高峰: ${dayStr}日 (${peakDisp})` :
                              activeLang === 'ja' ? `⚡ ピーク: ${dayStr}日 (${peakDisp})` :
                              `⚡ Peak: Day ${dayStr} (${peakDisp})`;
            badgeEl.textContent = peakLabel;
            badgeEl.style.display = 'inline-block';
        } else {
            badgeEl.style.display = 'none';
        }
    }

    const monthDaySumsDisp = monthDaySumsRon.map(v => convertFromRon(v, mainCurr));
    const dayLabels = Array.from({ length: 31 }, (_, i) => String(i + 1));

    // Culori: evidențiere elegantă pe ziua de vârf cu violet
    const bgColors = monthDaySumsRon.map(val => (val > 0 && val === peakSumRon) ? '#8b5cf6' : 'rgba(139, 92, 246, 0.55)');
    const hoverColors = monthDaySumsRon.map(val => (val > 0 && val === peakSumRon) ? '#7c3aed' : '#8b5cf6');

    const chartTextColor = getChartTextColor();
    const chartGridColor = getChartGridColor();

    if (statsMonthDaysChartInstance) {
        statsMonthDaysChartInstance.destroy();
    }

    statsMonthDaysChartInstance = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: dayLabels,
            datasets: [{
                label: `${t('stat_expense')} (${curSymbol})`,
                data: monthDaySumsDisp,
                backgroundColor: bgColors,
                hoverBackgroundColor: hoverColors,
                borderRadius: 3,
                barPercentage: 0.75
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    grid: { display: false },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 9 },
                        maxRotation: 0,
                        autoSkip: true,
                        maxTicksLimit: 16
                    }
                },
                y: {
                    grid: { color: chartGridColor },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 10 },
                        callback: (v) => v + ' ' + curSymbol
                    }
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        title: (items) => {
                            const dayNum = items[0].dataIndex + 1;
                            return activeLang === 'ro' ? `Ziua ${dayNum} a lunii` :
                                   activeLang === 'de' ? `Tag ${dayNum} des Monats` :
                                   activeLang === 'tr' ? `Ayın ${dayNum}. günü` :
                                   activeLang === 'zh' ? `${dayNum}日` :
                                   activeLang === 'ja' ? `${dayNum}日` :
                                   `Day ${dayNum} of month`;
                        },
                        label: (ctx) => {
                            const count = monthDayCounts[ctx.dataIndex];
                            const countTxt = activeLang === 'ro' ? `${count} plăți` :
                                             activeLang === 'de' ? `${count} Zahlungen` :
                                             activeLang === 'tr' ? `${count} işlem` :
                                             activeLang === 'zh' ? `${count}笔` :
                                             activeLang === 'ja' ? `${count}件` :
                                             `${count} payments`;
                            return ` ${formatMoney(ctx.raw, mainCurr)} (${countTxt})`;
                        }
                    }
                },
                datalabels: { display: false }
            }
        }
    });
}

// Grafic Nou: Clasament Locații din Toate Perioadele Cumulate (după totalul cumpărăturilor, fără suspendate)
function renderStatsLocationsAllTimeChart(mainCurr, curSymbol, activeLang) {
    const canvas = document.getElementById('statsLocationsBarChart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const locMap = {};
    if (Array.isArray(appData.transactions)) {
        appData.transactions.forEach(t => {
            if (!t || t.type !== 'expense') return;
            if (isTxEffectivelySuspended(t)) return;
            if (isSavingsCategory(t)) return;

            const locName = (t.location || '').trim();
            if (!locName) return;

            const key = locName.toLowerCase();
            const amtRon = parseFloat(t.amountInRon) || parseFloat(t.amount) || 0;
            if (amtRon <= 0) return;

            if (!locMap[key]) {
                locMap[key] = {
                    name: locName,
                    totalRon: 0,
                    count: 0
                };
            }
            locMap[key].totalRon += amtRon;
            locMap[key].count += 1;
        });
    }

    const locsList = Object.values(locMap).sort((a, b) => b.totalRon - a.totalRon);

    const badge = document.getElementById('statsLocationsTotalCountBadge');
    if (badge) {
        const locWord = activeLang === 'ro' ? (locsList.length === 1 ? 'Locație' : 'Locații') : (locsList.length === 1 ? 'Location' : 'Locations');
        badge.textContent = `${locsList.length} ${locWord}`;
    }

    const wrap = document.getElementById('wrapStatsLocationsBarChart');
    if (locsList.length === 0) {
        if (statsLocationsBarChartInstance) {
            statsLocationsBarChartInstance.destroy();
            statsLocationsBarChartInstance = null;
        }
        if (wrap) {
            wrap.innerHTML = `<canvas id="statsLocationsBarChart"></canvas><div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:0.78rem;color:var(--text-muted);">${activeLang === 'ro' ? 'Nu există cheltuieli cu locații asociate' : 'No location expense data'}</div>`;
        }
        return;
    } else {
        const existingNoData = wrap?.querySelector('div');
        if (existingNoData) existingNoData.remove();
    }

    // Top 15 locații
    const topLocs = locsList.slice(0, 15);
    const locLabels = topLocs.map(l => l.name);
    const locData = topLocs.map(l => convertFromRon(l.totalRon, mainCurr));

    if (wrap) {
        wrap.style.minHeight = Math.max(200, topLocs.length * 32) + 'px';
    }

    const chartTextColor = getChartTextColor();
    const chartGridColor = getChartGridColor();

    if (statsLocationsBarChartInstance) {
        statsLocationsBarChartInstance.destroy();
    }

    statsLocationsBarChartInstance = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: locLabels,
            datasets: [{
                label: `${activeLang === 'ro' ? 'Total Cheltuieli' : 'Total Expenses'} (${curSymbol})`,
                data: locData,
                backgroundColor: 'rgba(59, 130, 246, 0.82)',
                hoverBackgroundColor: '#3b82f6',
                borderRadius: 4,
                barPercentage: 0.7
            }]
        },
        options: {
            indexAxis: 'y',
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    grid: { color: chartGridColor },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 10 },
                        callback: (v) => v + ' ' + curSymbol
                    }
                },
                y: {
                    grid: { display: false },
                    ticks: {
                        color: chartTextColor,
                        font: { size: 10, weight: 'bold' }
                    }
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: (c) => {
                            const loc = topLocs[c.dataIndex];
                            const cntText = activeLang === 'ro' ? `${loc.count} achiziții` : `${loc.count} purchases`;
                            return ` ${formatMoney(c.raw, mainCurr)} • ${cntText}`;
                        }
                    }
                },
                datalabels: { display: false }
            }
        }
    });
}

