// Open Modal Helper
function openModal(modalId) {
    applyLanguage();
    // Prevenire suprapunere între ferestrele principale de tranzacție
    if (modalId === 'modalExpense') {
        closeModal('modalIncome');
        closeModal('modalTransfer');
    } else if (modalId === 'modalIncome') {
        closeModal('modalExpense');
        closeModal('modalTransfer');
    } else if (modalId === 'modalTransfer') {
        closeModal('modalExpense');
        closeModal('modalIncome');
    }
    const modal = document.getElementById(modalId);
    if (modal) {
        modal.scrollTop = 0;
        const box = modal.querySelector('.modal-box') || modal.querySelector('.modal-fullscreen-box');
        if (box) box.scrollTop = 0;
        window.scrollTo(0, 0);
        if (document.documentElement) document.documentElement.scrollTop = 0;
        if (document.body) document.body.scrollTop = 0;
        modal.classList.add('active');
        document.body.classList.add('modal-open');
        if (document.documentElement) document.documentElement.classList.add('modal-open');
    }
}

// Close Modal Helper
function closeModal(modalId) {
    if (modalId) {
        const modal = document.getElementById(modalId);
        if (modal) {
            modal.classList.remove('active');
        }
        if (modalId === 'modalExpense') {
            window._editingExpenseTx = null;
        }
    } else {
        document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active'));
        window._editingExpenseTx = null;
    }
    const hasActiveModal = !!document.querySelector('.modal-overlay.active');
    if (!hasActiveModal) {
        document.body.classList.remove('modal-open');
        if (document.documentElement) document.documentElement.classList.remove('modal-open');
    }
}

